const D = { density: .55, scale: 1, energy: .6, hue: 32, speed: 1, x: .5, y: .46, seed: 0, style: 'dune', act: 'drift' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:v>b?b:v;
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const sty = P.style, H = P.hue;
const hz = cl(P.y,.28,.72)*height, cx = cl(P.x,.05,.95)*width;
const groundH = Math.max(20, height - hz);
const yOf = t => hz + Math.pow(t,1.7)*groundH;
const hwOf = t => width*(.05 + t*.95)*.5*P.scale;
const NR = Math.round(10 + P.density*30);

// audio smoothed, blended on top of clk baseline
S.bass = (S.bass||0)*.82 + (A.bass||0)*.18;
S.tre  = (S.tre||0)*.82 + (A.treble||0)*.18;
const glow = (.4 + .6*P.energy) * (.55 + .55*K.intensity);
const kick = Math.min(1, K.pulse*(.5+.5*K.intensity) + S.bass*.7);

// real-time wind scroll (integrate real seconds -> never re-phases)
if (S.pt == null || K.t < S.pt) S.pt = K.t;
let dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
let sp = P.speed*(.5 + .8*K.intensity);
if (P.act === 'gust') sp *= 1 + 1.0*kick;
if (P.act === 'dusk') sp *= .4 + .8*(.5 + .5*Math.sin(K.t*.05 + K.section));
S.scroll = (S.scroll||0) + dt*sp*.5;
const scroll = S.scroll;
// dusk act slowly shifts the sand toward sunset amber
const dh = P.act==='dusk' ? (H - 14*(.5+.5*Math.sin(K.t*.045))) : H;

// ---- cached base: sky + graded sand plane + static dune shadows/grain ----
const key = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+P.seed+'|'+Math.round(P.density*6)+'|'+Math.round(P.y*24)+'|'+Math.round(P.scale*8);
if (!S.base || S.key !== key) {
  const g = (S.base && S.base.width===width && S.base.height===height) ? S.base : createGraphics(width,height);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const STR = 56;
  // sky above horizon
  for (let i=0;i<STR;i++){ const f=i/STR, y=f*hz; let h,s,b;
    if (sty==='thermal'){ h=232-70*f; s=64; b=6+14*f; }
    else if (sty==='cartography'){ h=H; s=22; b=6+5*f; }
    else if (sty==='noir'){ h=222; s=22-14*f; b=5+12*f; }
    else if (sty==='riso'){ h=(f<.5?18:190); s=42; b=12+16*f; }
    else { h=(H+16 - 22*f); s=44-18*f; b=30+50*f; } // dune dusk sky
    g.fill(h,s,cl(b,2,92),100); g.rect(0,y-1,width,hz/STR+2);
  }
  // horizon heat haze band
  if (sty!=='cartography'){ g.push(); g.blendMode(ADD);
    for (let i=0;i<7;i++){ const r=(7-i)*groundH*.05;
      g.fill(sty==='thermal'?42:(sty==='noir'?210:(H+8)), sty==='noir'?18:64, sty==='noir'?66:96, 8);
      g.rect(0, hz-r*.36, width, r); } g.pop(); }
  // sand plane gradient
  for (let i=0;i<STR;i++){ const t=i/STR, y=yOf(t), y2=yOf((i+1)/STR); let h,s,b;
    if (sty==='thermal'){ h=250-250*Math.pow(t,1.25); s=86; b=12+72*Math.pow(t,1.5); if(t>.86){h=46;s=cl(30-160*(t-.86),0,40);b=95;} }
    else if (sty==='cartography'){ h=H; s=26; b=8+16*t; }
    else if (sty==='noir'){ h=222; s=cl(16-14*t,0,18); b=8+40*Math.pow(t,1.3); }
    else if (sty==='riso'){ h=22; s=54-20*t; b=30+40*Math.pow(t,1.2); }
    else { h=(H+8 - 8*t); s=52-14*t; b=26 + 46*Math.pow(t,1.15); } // warm sand
    g.fill(h,s,cl(b,3,92),100); g.rect(0,y-1,width,(y2-y)+2);
  }
  // static long dune shadow bands (soft undulating) + grain
  g.push();
  if (sty==='cartography'){ // topographic contour lines = schematic, non-representational
    g.stroke(H,34,72,40); g.strokeWeight(1); g.noFill();
    for (let c=0;c<14;c++){ const base=fr(c*7)*groundH; g.beginShape();
      for (let xx=0;xx<=width;xx+=14){ const t=cl((base + Math.sin(xx*.004 + c*1.3 + fr(c*7+1)*6)*groundH*.10 + c*groundH*.02)/groundH,0,1);
        g.vertex(xx, yOf(cl(t,.02,1))); } g.endShape(); }
    g.stroke(H,30,52,18); for (let i=1;i<12;i++){ const y=i/12*hz; g.line(0,y,width,y); }
    g.noStroke();
  } else {
    g.blendMode(sty==='noir'?BLEND:MULTIPLY);
    for (let d=0;d<6;d++){ const dt2=(d+1)/7, y=yOf(dt2), hw=hwOf(dt2);
      const sh = sty==='noir'?color(220,20,18,26):color((H-6),50,40,22);
      g.fill(sh); g.noStroke();
      g.beginShape(); g.vertex(cx-hw,y);
      for (let xx=-hw;xx<=hw;xx+=hw/8){ g.vertex(cx+xx, y + Math.sin(xx*.01 + d*1.7 + fr(d)*6)*groundH*.03*dt2); }
      g.vertex(cx+hw,y+groundH*.05*dt2); g.vertex(cx-hw,y+groundH*.05*dt2); g.endShape(CLOSE); }
    // fine static grain
    g.blendMode(sty==='thermal'?ADD:MULTIPLY);
    for (let i=0;i<170;i++){ const t=.08+.92*fr(i*3), y=yOf(t), hw=hwOf(t), x=cx+(fr(i*3+1)*2-1)*hw;
      const gb = sty==='thermal'?color(38,70,90,5): sty==='riso'?color(i%2?188:20,60,60,10):color((H-4),40,30,10);
      g.fill(gb); g.ellipse(x,y,1+t*2.4,1+t*1.6); }
  }
  g.pop();
  S.base = g; S.key = key;
}
image(S.base,0,0);

// ---- live wind ripples scrolling toward viewer ----
noFill();
for (let r=0;r<=NR;r++){ let t=(r - (scroll%1))/NR; if (t<=0.01||t>1) continue;
  const y=yOf(t), hw=hwOf(t), near=t;
  let h,s,b,a,sw;
  if (sty==='thermal'){ h=250-250*Math.pow(t,1.25); s=90; b=100; a=10+46*near; sw=.5+near*2.0; }
  else if (sty==='cartography'){ h=H; s=30; b=88; a=12+40*near; sw=.5+near*1.3; }
  else if (sty==='noir'){ h=220; s=10; b=100; a=8+44*near; sw=.5+near*2.0; }
  else if (sty==='riso'){ h=(r%2?188:20); s=70; b=96; a=12+40*near; sw=.6+near*2.2; }
  else { h=(dh+10); s=30; b=94; a=10+44*near; sw=.5+near*2.4; } // dune crest highlight
  stroke(h,s,b, a*(.55+.6*glow));
  strokeWeight(sw);
  beginShape();
  for (let u=0;u<=1.001;u+=1/10){ const xx=-hw + u*2*hw;
    const wob = Math.sin(u*8 + r*.9 + K.t*.7)*groundH*.010*near + Math.sin(u*3 - scroll*1.3)*groundH*.014*near;
    vertex(cx+xx, y + wob); }
  endShape();
}

// ---- heat shimmer over the far plane (continuous, real-time) ----
if (sty!=='cartography'){ push(); blendMode(ADD); noStroke();
  for (let i=0;i<10;i++){ const t=.05+ i*.045, y=yOf(t), hw=hwOf(t);
    const off=Math.sin(K.t*2.2 + i*1.4)*width*.006*(1-t);
    fill(sty==='thermal'?44:(dh+6), sty==='noir'?12:56, sty==='noir'?70:96, 4+5*glow);
    rect(-off, y-groundH*.006, width+off*2, groundH*.016); }
  pop();
}

// ---- blowing sand grains: horizontal wind drift (real-time, never re-phases) ----
const NP = Math.round(P.density*70);
push(); blendMode(sty==='noir'?SCREEN:ADD); noStroke();
for (let i=0;i<NP;i++){ const t=.10+.88*fr(i*4);
  const y=yOf(t), hw=hwOf(t);
  const lane = fr(i*4+1);
  let px = ((lane + (scroll*.5 + K.t*.28)*(.4+.6*fr(i*4+2))) % 1); // wind blows across
  const x = cx + (px*2-1)*hw;
  const sz = (1.2 + 5*t) * (1 + .5*S.tre);
  let h = sty==='thermal'?(20+40*t): sty==='noir'?210: sty==='riso'?(i%2?188:22):(dh+6);
  let s = sty==='noir'?10:60;
  const a = (8 + 34*t) * (.5+.9*glow) * (.6+.7*fr(i*4+2));
  fill(h,s,100,Math.min(42,a));
  ellipse(x, y + Math.sin(K.t*1.1 + i)*groundH*.006*t, sz*2.2, sz);
}
pop();

// ---- sun/heat flare at horizon on the beat (partial-frame, strobe-safe) ----
push(); blendMode(ADD); noStroke();
const flare = (kick*.6 + K.swell*.4)*glow;
const fh = sty==='thermal'?46: sty==='noir'?214: (dh+4);
for (let i=0;i<5;i++){ const rr=(5-i)*groundH*.05*(1+flare);
  fill(fh, sty==='noir'?14:62, sty==='noir'?82:98, 3+8*flare);
  rect(0, hz-rr*.42, width, rr); }
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
